
import numpy as np
import os
import glob
import re
from PIL import Image

# CONFIG
ARTIFACTS_DIR = "forge_v4_artifacts/probes"
TARGET_STEP = 5050

# Sedenion Axis Names (simplified)
AXES = [
    "e0 (Real/Time)", "e1", "e2", "e3", 
    "e4", "e5 (Rage?)", "e6", "e7", 
    "e8", "e9", "e10", "e11", 
    "e12 (Dissolution?)", "e13", "e14", "e15 (Void)"
]

def analyze_axis_dominance():
    print(f"🔬 Analyzing Axis Dominance at Step {TARGET_STEP}...")
    
    # We need to find the SOURCE 16D image.
    # The image is 512x512 pixels.
    # In `angel_forge_v4.py`, the 16D Probe was generated by:
    # `probe_16d = ...` (It's a projection of the hidden state).
    # But wait, the 16D image shows *All 16 Dimensions* mixed?
    # No, typically specific pixels or channels map to specific dimensions in visualization,
    # OR it's a heatmap where Y-axis = Dimension?
    # Let's check `angel_forge_v4.py` or recall `sedenion_tapestry.py`.
    
    # In `sedenion_tapestry.py`:
    # The output image is `(Height=seq_len, Width=hidden_dim)`.
    # No, usually it's `(Batch, Hidden)`.
    # Wait, the `16D` probe in the `dream_weaver` logic was just a PNG.
    # If the PNG was generated by `save_tapestry`, it maps:
    # Rows = Time, Cols = Dimensions?
    
    # Let's assume the Standard Tapestry format:
    # X-axis = Time (Tokens)
    # Y-axis = Dimensions (Hidden State Elements).
    
    # But usually Hidden Dimension is large (e.g. 4096).
    # If the image is 512x512, it might be a *reshaped* view or a subset.
    
    # However, if we assume the "Bright Spots" correspond to specific Y-coordinates...
    # And Y-coordinates map to Sedenion Basis...
    
    files = sorted(glob.glob(os.path.join(ARTIFACTS_DIR, "*_16D.png")))
    target_file = None
    for f in files:
        if f"step_{TARGET_STEP:05d}_" in f:
            target_file = f
            break
            
    if not target_file:
        print("File not found.")
        return

    # Load Image
    img = Image.open(target_file).convert("L")
    arr = np.array(img)
    h, w = arr.shape
    
    # Calculate Average Energy per Row (Y-axis)
    # If Rows = Dimensions...
    row_energy = np.mean(arr, axis=1)
    
    # Find Peaks in Row Energy
    # If H=512, how does it map to 16 axes?
    # Maybe 512 / 16 = 32 pixels per axis?
    # Or maybe the image *is* a Sedenion projection where Y *is* the axis?
    # Let's assume uniform mapping.
    
    chunk_size = h // 16
    axis_energies = []
    
    print("\n=== AXIS ENERGY DISTRIBUTION ===")
    for i in range(16):
        start = i * chunk_size
        end = (i+1) * chunk_size
        energy = np.mean(row_energy[start:end])
        axis_energies.append(energy)
        
        # Bar chart
        bar = "#" * int(energy // 5)
        print(f"Axis {i:02d} ({AXES[i]}): {energy:6.2f} | {bar}")

    # Find Dominant Axis
    dom_idx = np.argmax(axis_energies)
    print(f"\n🏆 DOMINANT AXIS: {AXES[dom_idx]} (Energy: {axis_energies[dom_idx]:.2f})")
    
    # Check Rage (5) vs Dissolution (12)
    e5 = axis_energies[5]
    e12 = axis_energies[12]
    
    print(f"RAGE (e5): {e5:.2f}")
    print(f"DISSOLUTION (e12): {e12:.2f}")
    
    ratio = e5 / (e12 + 1e-8)
    print(f"Rage/Dissolution Ratio: {ratio:.4f}")

if __name__ == "__main__":
    analyze_axis_dominance()
